        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Disease progression will be assessed by the 8 in 1 score",
              "description": "Disease progression was assessed by the 8 in 1 score, which is a disease specific instrument adapted from other scores in neurodegenerative and lysosomal diseases (NPC, CLN). The instrument is designed to monitor disease progession and measure disease severity. The 8 in 1 score summarizes 8 domains (partizipation, medical care, ambulation, manipulation, swallowing, speech, epilepsy and cognition) ranging from 0 - 40. A higher score indicates more severe clinical impairment.",
              "timeFrame": "5 years"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Characterization of the first neurological symptom",
              "description": "In a systematic interview all aspects of medical history and development will be acquisited. The first neurological symptom will be reflected in view of parents/caregiver, GP and disease expert. The timepoint of occurrance and who recognized the finding will be evaluated.",
              "timeFrame": "5 years"
            }
          ]
        },
